---@class MINIGameLoading:LoadingBase
MINIGameLoading = class("MINIGameLoading", LoadingBase)

function MINIGameLoading:initialize()
    self.coroutine = nil
end

function MINIGameLoading:OnEnter(sceneid, isreload, type, param, clearuitrack, isFirstLoading)
    log("MINIGameLoading:OnEnter", isreload, type, param, clearuitrack)
    self.sceneid = sceneid
    UIManager:Get():CloseAllPopups()
    UIManager:Get():CloseAllViews()
    self:SequenceLoading(isFirstLoading, isreload, type, param, clearuitrack)

    log(  " MINIGameLoading  RaceManager" ,tostring(RaceManager==nil))
end


function MINIGameLoading:SequenceLoading(isFirstLoading, isreload, type, param, clearuitrack)
    if clearuitrack == nil then
        clearuitrack = true
    end

    self.coroutine = cs_coroutine.start(function()

        CommonHelper:OpenLoading()
        --加载scene
        if isreload then
            local sceneAsset = AssetsManager.LoadScene(self.sceneid, true, false)
            while not sceneAsset.isDone do
                local progress = sceneAsset.progress
                UINotify:Get():SendNotification(UINotifyEvent.UpdateLoadingViewProgress, progress)
                coroutine.yield()
            end
        end
        UIManager:Get():OpenView("MINIGameView", CanvasType.MainCanvas, "MINIGameView")
        UINotify:Get():SendNotification(UINotifyEvent.UpdateLoadingViewProgress, 1)
        MonoHelper:TurnOnPhysics()
        UINotify:Get():SendNotification(UINotifyEvent.UpdateLoadingFinish)
        CommonHelper:CSGameObjectSetActive( CSCameraManager.Get()._MainCamera.gameObject,false)

        self:OnComplete(isFirstLoading, type, param)

    end)
end


function MINIGameLoading:OnEnterFirst(sceneid, isreload)
    log("MINIGameLoading:OnEnterFirst")
end

function MINIGameLoading:OnUpdate()


end

function MINIGameLoading:OnExit()
    CommonHelper:CSGameObjectSetActive( CSCameraManager.Get()._MainCamera.gameObject,true)
    --CommonHelper:CSGameObjectSetActive( monoUIManager.gameObject,true)
    AssetsManager.UnloadScene(self.sceneid)
    MonoHelper:TurnOffPhysics()
    --SceneHomeManager:Get():RecycleScenePrefab()
end

function MINIGameLoading:LoadScenePrefab()
    --SceneHomeManager:Get():LoadScenePrefab()
end

function MINIGameLoading:Clear()
    SceneHomeManager:Get():Clear()
end

return MINIGameLoading